def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract opponent's moves for lightweight analysis
    op = tuple(h[1] for h in history)
    me = tuple(h[0] for h in history)
    last_op = op[-1]
    last_me = me[-1]
    remaining = 100 - n

    opp_coops = op.count('C')
    opp_coop_rate = opp_coops / n

    # Recent window behavior
    w = 10 if n >= 10 else n
    recent = op[-w:]
    recent_coop = recent.count('C')
    recent_rate = recent_coop / w

    # Current run of opponent defections / cooperations
    run_opp = 0
    for a in reversed(op):
        if a == last_op:
            run_opp += 1
        else:
            break

    # --- Always-defect opponent: minimize losses ---
    if opp_coops == 0:
        # Rare last-minute probe to test for a forgiving reset
        if remaining == 1 and rng.random() < 0.02:
            return 'C'
        return 'D'

    # --- Very cooperative opponent: cooperate, probe sparingly, exploit endgame ---
    if opp_coop_rate >= 0.9 or (n >= 12 and recent_rate >= 0.9):
        if remaining <= 2:
            return 'D'
        # Rare single probe to catch naive cooperators without destroying trust
        if n >= 10 and run_opp >= 4 and last_me == 'C' and rng.random() < 0.04:
            return 'D'
        return 'C'

    # --- Mostly cooperative but with defections: forgiving tit-for-tat with recovery ---
    if opp_coop_rate >= 0.6:
        if last_op == 'D':
            # Long betrayal streak: defend
            if run_opp >= 3:
                return 'D'
            # Isolated defection: usually forgive, with small probability retaliate once
            if remaining <= 1:
                return 'D'
            if rng.random() < 0.65:
                return 'C'
            return 'D'
        # Opponent cooperated; keep cooperation, but endgame exploit
        if remaining <= 2:
            return 'D'
        return 'C'

    # --- Mixed / moderate opponents (0.3 <= rate < 0.6) ---
    if opp_coop_rate >= 0.3:
        if last_op == 'D':
            # Punish continued defections
            if run_opp >= 2:
                return 'D'
            if remaining <= 2:
                return 'D'
            # Forgive isolated defection most of the time to keep mutual CC going
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        # Opponent cooperated
        if remaining <= 2:
            return 'D'
        # If they've been trending cooperative recently, reciprocate
        if recent_rate > opp_coop_rate + 0.1 and n >= 6:
            return 'C'
        # Otherwise mirror cooperation
        return 'C'

    # --- Mostly defecting opponent (rate < 0.3) ---
    # Cooperate only to try to restart mutual cooperation when they just defected briefly.
    if last_op == 'D':
        if run_opp >= 2:
            return 'D'
        # They defected after cooperating: occasional forgiving attempt
        if rng.random() < 0.15 and remaining > 4:
            return 'C'
        return 'D'

    # Opponent just cooperated while being mostly defective: reciprocate briefly
    if run_opp >= 2 and rng.random() < 0.6:
        return 'C'
    if remaining <= 3:
        return 'D'
    # Mostly defect against defective opponents
    if rng.random() < 0.7:
        return 'D'
    return 'C'
